visibility_probe.source:
extends SceneTree

func measure(node: Node) -> Dictionary:
	var result := {"nodes": 1, "meshes": int(node is MeshInstance3D), "markers": int(node is Marker3D), "colliders": int(node is CollisionShape3D)}
	for child in node.get_children():
		var sub := measure(child)
		for key in result: result[key] += sub[key]
	return result

func _initialize() -> void:
	_run.call_deferred()

func _run() -> void:
	var reports: Array = []
	for path in ["res://scenes/areas/street_district.tscn", "res://scenes/battle/urban_arena.tscn", "res://scenes/areas/first_mission.tscn", "res://scenes/weapons/assault_rifle.tscn", "res://scenes/presentation/compact_hideout/environment.tscn"]:
		var scene: PackedScene = load(path)
		var instance: Node = scene.instantiate()
		var saved := measure(instance)
		root.add_child(instance)
		for frame in 3: await process_frame
		var runtime := measure(instance)
		var row := {"path": path, "before_ready": saved, "after_ready": runtime}
		reports.append(row)
		print(JSON.stringify(row))
		instance.queue_free()
		await process_frame
	var file := FileAccess.open("C:/Users/admin/AppData/Local/Temp/bunny_tool_research_20261014_7hbge00t/editor_visibility_counts.json", FileAccess.WRITE)
	file.store_string(JSON.stringify(reports, "\t"))
	file.close()
	root.get_node("AudioDirector").shutdown_for_test()
	quit()
